__device__ float read_lane18(float value)
{
    const unsigned int thread_rank =
        threadIdx.x + blockDim.x *
        (threadIdx.y + blockDim.y * threadIdx.z);
    const unsigned int lane = thread_rank % 32u;
    const bool participates = lane <= 18u;
    const unsigned int mask =
        __ballot_sync(0xffffffffu, participates);

    if (participates) {
        value = __shfl_sync(mask, value, 18, 32);
    }
    return value;
}
```

