Move the barrier outside the conditional. This complete example accepts `valid` from 0 through 96 and defines the empty sum as zero:

```cpp
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t err)
{
    if (err != cudaSuccess) {
        std::fprintf(stderr, "CUDA error: %s\n",
                     cudaGetErrorString(err));
        std::exit(EXIT_FAILURE);
    }
}

__global__ void sum_valid(const float* input, float* output, int valid)
{
    __shared__ float values[96];
    const unsigned int i = threadIdx.x;

    // Only valid inputs are read; every shared slot is initialized.
    values[i] = (i < static_cast<unsigned int>(valid))
                    ? input[i] : 0.0f;

    __syncthreads();

    if (i == 0) {
        float sum = 0.0f;
        for (int j = 0; j < valid; ++j) {
            sum += values[j];
        }
        *output = sum;
    }
}

// Requires input to contain at least valid device floats and output
// to contain one device float. Launches exactly one 96-thread block.
static void launch_sum(const float* input, float* output,
                       int valid, cudaStream_t stream)
{
    if (valid < 0 || valid > 96) {
        std::fprintf(stderr, "valid must be between 0 and 96\n");
        std::exit(EXIT_FAILURE);
    }
    sum_valid<<<1, 96, 0, stream>>>(input, output, valid);
    check(cudaGetLastError());
}

int main(int argc, char** argv)
{
    int valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        const long parsed = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' ||
            parsed < 0 || parsed > 96) {
            std::fprintf(stderr, "valid must be between 0 and 96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(parsed);
    }

    float input[96];
    for (float& value : input) value = 1.0f;
    float result = -1.0f;
    float* device_input = nullptr;
    float* device_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t done;

    check(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    check(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));
    check(cudaMalloc(reinterpret_cast<void**>(&device_input),
                     sizeof(input)));
    check(cudaMalloc(reinterpret_cast<void**>(&device_output),
                     sizeof(float)));

    check(cudaMemcpy(device_input, input, sizeof(input),
                     cudaMemcpyHostToDevice));
    launch_sum(device_input, device_output, valid, stream);
    check(cudaEventRecord(done, stream));
    check(cudaEventSynchronize(done));
    check(cudaMemcpy(&result, device_output, sizeof(result),
